        )

    lines.extend(["", f"## {labels['blockers']}", ""])
    blockers = [(task.get("id", ""), blocker) for task in status["tasks"] for blocker in task.get("blockers", [])]
    if blockers:
        for task_id, blocker in blockers:
            lines.append(f"- `{task_id}`: {blocker}")
    else:
        lines.append("- None")

    return "\n".join(lines)


