          </article>"""


def render_task_row(task: JsonMap, root: Path) -> str:
    timing = timing_summary_for_task(task, root)
    return f"""<tr>
              <td>{escape(task.get("id", ""))}</td>
              <td>{escape(task.get("title", ""))}</td>
