from pathlib import Path

from workspace_health.models import Check


def run_check(check: Check) -> subprocess.CompletedProcess[str]:
    env = os.environ.copy()
    if check.env:
        env.update(check.env)
    return subprocess.run(
        check.args,
        cwd=check.cwd,
        env=env,
        text=True,
        capture_output=True,
        check=False,
    )


def serialize_check(check: Check, root: Path) -> dict[str, str]:
    return {
        "name": check.name,
        "category": check.category,
        "cwd": relative_cwd(check.cwd, root),
        "command": " ".join(check.args),
    }


def serialize_result(check: Check, result: subprocess.CompletedProcess[str], root: Path) -> dict[str, object]:
    data: dict[str, object] = serialize_check(check, root)
    data.update(
        {
            "status": "ok" if result.returncode == 0 else "fail",
            "returncode": result.returncode,
        }
    )
    if result.returncode != 0:
        data["stdout"] = result.stdout
        data["stderr"] = result.stderr
    return data


def format_command(check: Check, root: Path | None = None) -> str:
    cwd = relative_cwd(check.cwd, root) if root else str(check.cwd)
    return f"(cd {cwd} && {' '.join(check.args)})"


def relative_cwd(cwd: Path, root: Path | None) -> str:
    if not root:
        return str(cwd)
    try:
        relative = cwd.relative_to(root)
    except ValueError:
        return str(cwd)
    return "." if not relative.parts else relative.as_posix()

from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path
from typing import Any


IGNORE_DIRS = {
    ".git",
    ".next",
    ".pytest_cache",
    "__pycache__",
    ".venv",
    "venv",
    "node_modules",
    "dist",
    "build",
    "coverage",
    "out",
}

ROOT_PURPOSES = {
    "_ops": "operations hub, prompts, workflows, and maps",
    "_docs": "workspace-level rules, decisions, and operating docs",
    "_philosophy": "foundational agent and platform operating philosophy",
    "_history": "dated work logs and compressed context",
    "_research": "reusable internet research and external reference notes",
    "_skills": "tracked source for custom Codex skills",
    "_templates": "reusable project and artifact templates",
    "_tools": "local tools that reduce repeated work",
    "_archive": "paused or retired projects",
    "agent-platform": "core personal agent-building platform project",
}


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Generate operations maps.")
    parser.add_argument("--root", type=Path, default=Path(__file__).resolve().parents[3])
    parser.add_argument("--check", action="store_true", help="Fail if maps are stale.")
    args = parser.parse_args(argv)

    root = args.root.resolve()
    outputs = {
        root / "_ops" / "maps" / "repository-map.md": render_repository_map(root),
        root / "_ops" / "maps" / "prompt-map.md": render_prompt_map(root),
    }

    stale = []
    for path, content in outputs.items():
        normalized = content.rstrip() + "\n"
        if args.check:
            if not path.exists() or path.read_text(encoding="utf-8") != normalized:
                stale.append(path)
            continue
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(normalized, encoding="utf-8")

    if args.check and stale:
        for path in stale:
            print(f"stale: {path.relative_to(root)}", file=sys.stderr)
        return 1

    if not args.check:
        for path in outputs:
            print(f"updated: {path.relative_to(root)}")
    return 0


def render_repository_map(root: Path) -> str:
    ignored_parts = IGNORE_DIRS | load_generated_ignore_parts(root)
    files = sorted(
        path.relative_to(root)
        for path in root.rglob("*")
        if path.is_file() and not should_ignore_with_parts(path.relative_to(root), ignored_parts)
    )
    root_entries = sorted(path for path in root.iterdir() if path.is_dir() and path.name not in ignored_parts)
    root_metadata = load_root_folder_metadata(root)

    lines = [
        "# Repository Map",
        "",
        "Generated by `_tools/workspace-index/src/workspace_index.py`.",
        "",
        "## Root Folders",
        "",
        "| Path | Class | Purpose | Source |",
        "| --- | --- | --- | --- |",
    ]

    for entry in root_entries:
        metadata = root_metadata.get(
            entry.name,
            {
                "class": "unclassified",
                "purpose": "project or workspace folder",
                "source": "workspace-index fallback",
            },
        )
        lines.append(
            f"| `{entry.name}/` | {metadata['class']} | {metadata['purpose']} | {metadata['source']} |"
        )

    lines.extend(
        [
            "",
            "## Key Start Points",
            "",
            "- `_ops/index.md`: operations navigation",
            "- `_ops/prompts/00-router.md`: prompt selection",
            "- `_ops/workflows/00-start-here.md`: default work sequence",
            "- `_docs/instructions/persistent-instructions.md`: durable user instructions",
            "- `agent-platform/README.md`: platform project overview",
            "",
            "## File Index",
            "",
        ]
    )

    current_group = ""
    for file_path in files:
        group = file_path.parts[0]
        if group != current_group:
            current_group = group
            if lines[-1] != "":
                lines.append("")
            lines.extend([f"### `{group}`", ""])
        lines.append(f"- `{file_path.as_posix()}`")

    return "\n".join(lines)


def load_root_folder_metadata(root: Path) -> dict[str, dict[str, str]]:
    metadata = {
        name: {"class": "known_root", "purpose": purpose, "source": "workspace-index built-in"}
        for name, purpose in ROOT_PURPOSES.items()
    }

    policy_path = root / "_ops" / "projects" / "root-structure-policy.json"
    policy = read_json(policy_path)
    if policy:
        for field_name, class_name in [
            ("reserved_operational_dirs", "reserved_operational"),
            ("local_only_dirs", "local_only"),
            ("runtime_adapter_dirs", "runtime_adapter"),
        ]:
            for item in list_of_dicts(policy.get(field_name, [])):
                name = str(item.get("name", "")).strip()
                if not name:
                    continue
                metadata[name] = {
                    "class": class_name,
                    "purpose": str(item.get("purpose", "")).strip() or metadata.get(name, {}).get("purpose", ""),
                    "source": policy_path.relative_to(root).as_posix(),
                }

    registry_path = root / str(policy.get("project_registry_path", "_ops/projects/registry.json")) if policy else root / "_ops" / "projects" / "registry.json"
    registry = read_json(registry_path)
    for project in list_of_dicts(registry.get("projects", [])):
        project_root = root_folder_name(str(project.get("path", project.get("name", ""))))
        if not project_root:
            continue
        metadata[project_root] = {
            "class": "registered_project",
            "purpose": str(project.get("purpose", "")).strip() or metadata.get(project_root, {}).get("purpose", ""),
            "source": registry_path.relative_to(root).as_posix(),
        }

    return metadata


def render_prompt_map(root: Path) -> str:
    prompt_files = sorted((root / "_ops" / "prompts").glob("*.md"))
    workflow_files = sorted((root / "_ops" / "workflows").glob("*.md"))

    lines = [
        "# Prompt Map",
        "",
        "Generated by `_tools/workspace-index/src/workspace_index.py`.",
        "",
        "## Prompts",
        "",
        "| Prompt | Use When |",
        "| --- | --- |",
    ]

    for path in prompt_files:
        lines.append(f"| `{path.relative_to(root).as_posix()}` | {extract_use_when(path)} |")

    lines.extend(["", "## Workflows", "", "| Workflow | Purpose |", "| --- | --- |"])
    for path in workflow_files:
        lines.append(f"| `{path.relative_to(root).as_posix()}` | {extract_section_summary(path, '## Purpose')} |")

    lines.extend(
        [
            "",
            "## Default Route",
            "",
            "1. `_ops/prompts/00-router.md`",
            "2. Matching prompt file",
            "3. Matching workflow file",
            "4. `_ops/maps/repository-map.md` when location is unclear",
        ]
    )

    return "\n".join(lines)


def should_ignore(relative_path: Path) -> bool:
    return should_ignore_with_parts(relative_path, IGNORE_DIRS)


def should_ignore_with_parts(relative_path: Path, ignored_parts: set[str]) -> bool:
    return any(part in ignored_parts for part in relative_path.parts)


def load_generated_ignore_parts(root: Path) -> set[str]:
    policy_path = root / "_ops" / "projects" / "root-structure-policy.json"
    policy = read_json(policy_path)
    parts = set()
    for item in list_of_dicts(policy.get("generated_output_dirs", [])):
        pattern = str(item.get("pattern", "")).strip().rstrip("/")
        if not pattern:
            continue
        leaf = pattern.split("/")[-1]
        if leaf and "*" not in leaf:
            parts.add(leaf)
    return parts


def read_json(path: Path) -> dict[str, Any]:
    if not path.exists():
        return {}
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError:
        return {}
    return data if isinstance(data, dict) else {}


def list_of_dicts(value: Any) -> list[dict[str, Any]]:
    if not isinstance(value, list):
        return []
    return [item for item in value if isinstance(item, dict)]


def root_folder_name(path_value: str) -> str:
    stripped = path_value.strip().strip("/")
    if not stripped:
        return ""
    return Path(stripped).parts[0]


def extract_use_when(path: Path) -> str:
    for line in path.read_text(encoding="utf-8").splitlines():
        if line.startswith("Use when:"):
            return line.removeprefix("Use when:").strip()
    return first_heading(path)


def extract_section_summary(path: Path, heading: str) -> str:
    lines = path.read_text(encoding="utf-8").splitlines()
    for index, line in enumerate(lines):
        if line.strip() == heading:
            for candidate in lines[index + 1 :]:
                candidate = candidate.strip()
                if candidate and not candidate.startswith("#"):
                    return candidate
    return first_heading(path)


def first_heading(path: Path) -> str:
    for line in path.read_text(encoding="utf-8").splitlines():
        if line.startswith("# "):
            return line.removeprefix("# ").strip()
    return path.stem


if __name__ == "__main__":
    raise SystemExit(main())

"""Structured models used by the platform core."""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any


JsonMap = dict[str, Any]


def _tuple_of_strings(value: Any, field_name: str) -> tuple[str, ...]:
    if value is None:
        return ()
    if not isinstance(value, list | tuple):
        raise TypeError(f"{field_name} must be a list of strings.")
    if not all(isinstance(item, str) for item in value):
        raise TypeError(f"{field_name} must contain only strings.")
    return tuple(value)


@dataclass(frozen=True)
class AgentSpec:
    """Declarative description of an agent."""

    name: str
    description: str
    runtime: str = "python"
    skills: tuple[str, ...] = ()
    tools: tuple[str, ...] = ()
    metadata: JsonMap = field(default_factory=dict)

    @classmethod
    def from_dict(cls, data: JsonMap) -> "AgentSpec":
        name = data.get("name")
        description = data.get("description")
        if not isinstance(name, str) or not name:
            raise ValueError("Agent spec requires a non-empty string name.")
        if not isinstance(description, str) or not description:
            raise ValueError("Agent spec requires a non-empty string description.")

        runtime = data.get("runtime", "python")
        if not isinstance(runtime, str) or not runtime:
            raise ValueError("Agent spec runtime must be a non-empty string.")

        metadata = data.get("metadata", {})
        if not isinstance(metadata, dict):
            raise TypeError("Agent spec metadata must be an object.")

        return cls(
            name=name,
            description=description,
            runtime=runtime,
            skills=_tuple_of_strings(data.get("skills", []), "skills"),
            tools=_tuple_of_strings(data.get("tools", []), "tools"),
            metadata=metadata,
        )

    def to_dict(self) -> JsonMap:
        return {
            "name": self.name,
            "description": self.description,
            "runtime": self.runtime,
            "skills": list(self.skills),
            "tools": list(self.tools),
            "metadata": self.metadata,
        }


@dataclass(frozen=True)
class ExecutionRequest:
    """Input passed to a runtime when executing an agent."""

    prompt: str
    context: JsonMap = field(default_factory=dict)


@dataclass(frozen=True)
class ExecutionResult:
    """Normalized runtime output."""

    output: str
    trace: tuple[str, ...] = ()
    artifacts: tuple[str, ...] = ()

"""Agent spec loading and in-memory registry."""

from __future__ import annotations

import json
from pathlib import Path

from agent_platform.core.models import AgentSpec


class AgentRegistry:
    """Small registry for declarative agent specs."""

    def __init__(self) -> None:
        self._agents: dict[str, AgentSpec] = {}

    def add(self, agent: AgentSpec) -> None:
        if agent.name in self._agents:
            raise ValueError(f"Duplicate agent name: {agent.name}")
        self._agents[agent.name] = agent

    def get(self, name: str) -> AgentSpec:
        try:
            return self._agents[name]
        except KeyError as exc:
            raise KeyError(f"Unknown agent: {name}") from exc

    def list_agents(self) -> tuple[AgentSpec, ...]:
        return tuple(self._agents[name] for name in sorted(self._agents))


def load_agent_spec(path: Path) -> AgentSpec:
    with path.open("r", encoding="utf-8") as file:
        data = json.load(file)
    return AgentSpec.from_dict(data)


def load_registry_dir(path: Path) -> AgentRegistry:
    registry = AgentRegistry()
    if not path.exists():
        return registry

    for spec_path in sorted(path.glob("*.json")):
        registry.add(load_agent_spec(spec_path))
    return registry

"""Runtime interfaces for executing agents."""

from __future__ import annotations

from collections.abc import Callable
from typing import Protocol

from agent_platform.core.models import AgentSpec, ExecutionRequest, ExecutionResult


class AgentRuntime(Protocol):
    """Adapter boundary for Python and open-source agent runtimes."""

    def run(self, agent: AgentSpec, request: ExecutionRequest) -> ExecutionResult:
        """Execute an agent and return a normalized result."""


AgentCallable = Callable[[AgentSpec, ExecutionRequest], ExecutionResult | str]


class PythonFunctionRuntime:
    """Minimal Python runtime backed by a plain callable."""

    def __init__(self, handler: AgentCallable) -> None:
        self._handler = handler

    def run(self, agent: AgentSpec, request: ExecutionRequest) -> ExecutionResult:
        result = self._handler(agent, request)
        if isinstance(result, ExecutionResult):
            return result
        return ExecutionResult(output=str(result), trace=("python-function-runtime",))

"""Check whether factual claims are grounded before publication."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any


JsonMap = dict[str, Any]

FACTUAL_CLAIM_TYPES = {
    "repository_state",
    "external_fact",
    "code_behavior",
    "calculation",
    "research_summary",
    "recommendation",
}

EVIDENCE_TYPES = {
    "user_instruction",
    "repository_file",
    "command_output",
    "test_result",
    "official_docs",
    "paper",
    "web_source",
    "dataset",
    "tool_result",
    "inference",
}

SUPPORTED_LEVELS = {"supported", "partially_supported", "unsupported", "uncertain", "not_checked"}
RISK_LEVELS = {"low", "medium", "high"}


@dataclass(frozen=True)
class EvidenceItem:
    """Evidence used to support a claim."""

    evidence_id: str
    source: str
    source_type: str
    checked_on: str = ""
    reliability: str = ""

    @classmethod
    def from_dict(cls, data: JsonMap) -> "EvidenceItem":
        return cls(
            evidence_id=_required_string(data, "evidence_id"),
            source=_required_string(data, "source"),
            source_type=_required_string(data, "source_type"),
            checked_on=_optional_string(data.get("checked_on", ""), "checked_on"),
            reliability=_optional_string(data.get("reliability", ""), "reliability"),
        )


@dataclass(frozen=True)
class ClaimCheck:
    """One claim extracted from an answer or artifact."""

    statement: str
    claim_type: str
    support_level: str
    evidence_ids: tuple[str, ...] = ()
    verification_steps: tuple[str, ...] = ()
    presented_as_fact: bool = True
    freshness_sensitive: bool = False

    @classmethod
    def from_dict(cls, data: JsonMap) -> "ClaimCheck":
        return cls(
            statement=_required_string(data, "statement"),
            claim_type=_required_string(data, "claim_type"),
            support_level=_required_string(data, "support_level"),
            evidence_ids=_tuple_of_strings(data.get("evidence_ids", []), "evidence_ids"),
            verification_steps=_tuple_of_strings(data.get("verification_steps", []), "verification_steps"),
            presented_as_fact=_optional_bool(data.get("presented_as_fact", True), "presented_as_fact"),
            freshness_sensitive=_optional_bool(data.get("freshness_sensitive", False), "freshness_sensitive"),
        )


@dataclass(frozen=True)
class HallucinationGuardInput:
    """Input for grounding an answer or artifact before it is treated as final."""

    task: str
    output_summary: str
    risk_level: str = "medium"
    evidence: tuple[EvidenceItem, ...] = ()
    claims: tuple[ClaimCheck, ...] = ()
    uncertainty_notes: tuple[str, ...] = ()
    limitation_notes: tuple[str, ...] = ()

    @classmethod
    def from_dict(cls, data: JsonMap) -> "HallucinationGuardInput":
        return cls(
            task=_required_string(data, "task"),
            output_summary=_required_string(data, "output_summary"),
            risk_level=_optional_string(data.get("risk_level", "medium"), "risk_level"),
            evidence=tuple(EvidenceItem.from_dict(item) for item in _list_of_maps(data.get("evidence", []), "evidence")),
            claims=tuple(ClaimCheck.from_dict(item) for item in _list_of_maps(data.get("claims", []), "claims")),
            uncertainty_notes=_tuple_of_strings(data.get("uncertainty_notes", []), "uncertainty_notes"),
            limitation_notes=_tuple_of_strings(data.get("limitation_notes", []), "limitation_notes"),
        )


def check_hallucination_risk(guard_input: HallucinationGuardInput) -> JsonMap:
    """Return a deterministic grounding report for factual claims."""

    gaps = _missing_required_fields(guard_input)
    warnings = []

    if guard_input.risk_level not in RISK_LEVELS:
        gaps.append(f"Unknown risk_level: {guard_input.risk_level}.")

    evidence_by_id = {item.evidence_id: item for item in guard_input.evidence}
    if len(evidence_by_id) != len(guard_input.evidence):
        gaps.append("Evidence IDs must be unique.")

    if not guard_input.evidence:
        gaps.append("Evidence is missing; factual claims need source, tool, or command grounding.")

    for evidence in guard_input.evidence:
        gaps.extend(_validate_evidence_item(evidence))

    for index, claim in enumerate(guard_input.claims, start=1):
        gaps.extend(_validate_claim(index, claim, evidence_by_id, guard_input.risk_level))
        warnings.extend(_claim_warnings(index, claim, guard_input.uncertainty_notes))

    if guard_input.risk_level == "high":
        independent_sources = {
            evidence.source
            for evidence in guard_input.evidence
            if evidence.source_type not in {"inference", "user_instruction"}
        }
        if len(independent_sources) < 2:
            gaps.append("High-risk factual output requires at least two independent non-inference evidence sources.")

    status = "grounding_required" if gaps else "ready_to_publish"

    return {
        "status": status,
        "requires_rework": bool(gaps),
        "principle": "Publish only claims that are grounded, verified, or explicitly caveated.",
        "checks": {
            "risk_level": guard_input.risk_level,
            "claims_count": len(guard_input.claims),
            "evidence_count": len(guard_input.evidence),
            "uncertainty_notes_count": len(guard_input.uncertainty_notes),
            "limitation_notes_count": len(guard_input.limitation_notes),
        },
        "gaps": gaps,
        "warnings": warnings,
        "follow_up_actions": [f"Resolve grounding gap: {gap}" for gap in gaps],
    }


def _validate_evidence_item(evidence: EvidenceItem) -> list[str]:
    gaps = []
    if not evidence.evidence_id.strip():
        gaps.append("Evidence item has an empty evidence_id.")
    if not evidence.source.strip():
        gaps.append(f"Evidence {evidence.evidence_id} is missing source.")
    if evidence.source_type not in EVIDENCE_TYPES:
        gaps.append(f"Evidence {evidence.evidence_id} has unknown source_type: {evidence.source_type}.")
    if evidence.source_type in {"official_docs", "paper", "web_source", "dataset"} and not evidence.checked_on.strip():
        gaps.append(f"Evidence {evidence.evidence_id} needs checked_on for external or time-sensitive sources.")
    return gaps


def _validate_claim(
    index: int,
    claim: ClaimCheck,
    evidence_by_id: dict[str, EvidenceItem],
    risk_level: str,
) -> list[str]:
    gaps = []
    label = f"Claim {index}"

    if not claim.statement.strip():
        gaps.append(f"{label} statement is missing.")
    if claim.claim_type not in FACTUAL_CLAIM_TYPES and claim.claim_type not in {"user_instruction", "inference", "preference"}:
        gaps.append(f"{label} has unknown claim_type: {claim.claim_type}.")
    if claim.support_level not in SUPPORTED_LEVELS:
        gaps.append(f"{label} has unknown support_level: {claim.support_level}.")

    unknown_ids = [evidence_id for evidence_id in claim.evidence_ids if evidence_id not in evidence_by_id]
    if unknown_ids:
        gaps.append(f"{label} references unknown evidence IDs: {', '.join(unknown_ids)}.")

    if _needs_grounding(claim):
        if not claim.evidence_ids:
            gaps.append(f"{label} is factual and presented as fact, but has no evidence IDs.")
        if not claim.verification_steps:
            gaps.append(f"{label} is factual and presented as fact, but has no verification steps.")
        if claim.support_level in {"unsupported", "not_checked"}:
            gaps.append(f"{label} is presented as fact but support_level is {claim.support_level}.")
        if claim.support_level == "uncertain":
            gaps.append(f"{label} is presented as fact but remains uncertain.")
        if risk_level in {"medium", "high"} and claim.support_level == "partially_supported":
            gaps.append(f"{label} is only partially supported for a {risk_level}-risk output.")

    if claim.claim_type == "external_fact":
        evidence_types = {evidence_by_id[evidence_id].source_type for evidence_id in claim.evidence_ids if evidence_id in evidence_by_id}
        if not evidence_types.intersection({"official_docs", "paper", "web_source", "dataset"}):
            gaps.append(f"{label} is an external fact but lacks external evidence.")

    if claim.claim_type in {"repository_state", "code_behavior"}:
        evidence_types = {evidence_by_id[evidence_id].source_type for evidence_id in claim.evidence_ids if evidence_id in evidence_by_id}
        if not evidence_types.intersection({"repository_file", "command_output", "test_result", "tool_result"}):
            gaps.append(f"{label} concerns repository/code state but lacks repository, command, test, or tool evidence.")

    if claim.freshness_sensitive:
        dated_evidence = [
            evidence_by_id[evidence_id]
            for evidence_id in claim.evidence_ids
            if evidence_id in evidence_by_id and evidence_by_id[evidence_id].checked_on.strip()
        ]
        if not dated_evidence:
            gaps.append(f"{label} is freshness-sensitive but has no dated evidence.")

    return gaps


def _claim_warnings(index: int, claim: ClaimCheck, uncertainty_notes: tuple[str, ...]) -> list[str]:
    warnings = []
    if claim.support_level in {"uncertain", "partially_supported"} and not uncertainty_notes:
        warnings.append(f"Claim {index} has limited support; add uncertainty notes or remove the claim.")
    if not claim.presented_as_fact and claim.support_level in {"unsupported", "not_checked"}:
        warnings.append(f"Claim {index} should remain explicitly caveated in the final output.")
    return warnings


def _needs_grounding(claim: ClaimCheck) -> bool:
    return claim.presented_as_fact and claim.claim_type in FACTUAL_CLAIM_TYPES


def _missing_required_fields(guard_input: HallucinationGuardInput) -> list[str]:
    missing = []
    if not guard_input.task.strip():
        missing.append("Task is missing.")
    if not guard_input.output_summary.strip():
        missing.append("Output summary is missing.")
    if not guard_input.claims:
        missing.append("Claims are missing; extract factual claims before publishing.")
    return missing


def _required_string(data: JsonMap, field_name: str) -> str:
    value = data.get(field_name)
    if not isinstance(value, str):
        raise TypeError(f"{field_name} must be a string.")
    return value


def _optional_string(value: Any, field_name: str) -> str:
    if not isinstance(value, str):
        raise TypeError(f"{field_name} must be a string.")
    return value


def _optional_bool(value: Any, field_name: str) -> bool:
    if not isinstance(value, bool):
        raise TypeError(f"{field_name} must be a boolean.")
    return value


