    "CHANGELOG.md",
}


@dataclass(frozen=True)
class SkillValidationInput:
    """Input for validating a custom skill before close-out or installation."""

    skill_path: str
    intended_use: str
    trigger_examples: tuple[str, ...] = ()
    validation_steps: tuple[str, ...] = ()
    forward_test_scenarios: tuple[str, ...] = ()
    improvement_ideas: tuple[str, ...] = ()
    known_gaps: tuple[str, ...] = ()

    @classmethod
    def from_dict(cls, data: JsonMap) -> "SkillValidationInput":
        return cls(
            skill_path=_required_string(data, "skill_path"),
            intended_use=_required_string(data, "intended_use"),
            trigger_examples=_tuple_of_strings(data.get("trigger_examples", []), "trigger_examples"),
            validation_steps=_tuple_of_strings(data.get("validation_steps", []), "validation_steps"),
            forward_test_scenarios=_tuple_of_strings(data.get("forward_test_scenarios", []), "forward_test_scenarios"),
            improvement_ideas=_tuple_of_strings(data.get("improvement_ideas", []), "improvement_ideas"),
            known_gaps=_tuple_of_strings(data.get("known_gaps", []), "known_gaps"),
        )


def validate_skill_definition(validation_input: SkillValidationInput, repo_root: Path | None = None) -> JsonMap:
    """Return a deterministic validation report for a skill source folder."""

    root = repo_root if repo_root is not None else Path.cwd()
    skill_path = Path(validation_input.skill_path)
    if not skill_path.is_absolute():
        skill_path = root / skill_path
    skill_path = skill_path.resolve()

    gaps = list(validation_input.known_gaps)
    warnings: list[str] = []

    if not validation_input.skill_path.strip():
        gaps.append("Skill path is missing.")
    if not validation_input.intended_use.strip():
        gaps.append("Intended use is missing.")
    if len(validation_input.trigger_examples) < 2:
        gaps.append("At least two trigger examples are required.")
    if not validation_input.validation_steps:
        gaps.append("Validation steps are missing.")
    if not validation_input.forward_test_scenarios:
        gaps.append("Forward-test scenarios are missing.")
    if not validation_input.improvement_ideas:
        warnings.append("Improvement ideas are missing; record at least one next improvement or explain that none were found.")

    if not skill_path.exists() or not skill_path.is_dir():
        gaps.append(f"Skill folder does not exist: {validation_input.skill_path}.")
        return _report(validation_input, gaps, warnings, skill_path, {}, 0)

    try:
        relative_path = skill_path.relative_to(root.resolve())
    except ValueError:
        relative_path = skill_path

    relative_path_text = str(relative_path)
    if not (relative_path_text.startswith("_skills/") or "/skills/" in relative_path_text):
        gaps.append("Skill source should live under _skills/<skill-name>/ or the owning project's skills/ folder.")

    skill_md = skill_path / "SKILL.md"
    if not skill_md.exists():
        gaps.append("SKILL.md is missing.")
        return _report(validation_input, gaps, warnings, skill_path, {}, 0)

    content = skill_md.read_text(encoding="utf-8")
    frontmatter, body, parse_gap = _parse_frontmatter(content)
    if parse_gap:
        gaps.append(parse_gap)
    else:
        gaps.extend(_validate_frontmatter(frontmatter, skill_path.name))
        gaps.extend(_validate_body(body))
        warnings.extend(_body_warnings(body))

    disallowed = sorted(path.name for path in skill_path.iterdir() if path.name in DISALLOWED_SKILL_DOCS)
    if disallowed:
        gaps.append(f"Skill folder contains non-skill documentation files: {', '.join(disallowed)}.")

    line_count = len(content.splitlines())
    if line_count > MAX_SKILL_MD_LINES:
        gaps.append(f"SKILL.md is too long ({line_count} lines). Keep it under {MAX_SKILL_MD_LINES} lines and move detail to references/.")

    if not (skill_path / "agents" / "openai.yaml").exists():
        warnings.append("agents/openai.yaml is missing; add UI metadata unless the skill is intentionally source-only.")

    return _report(validation_input, gaps, warnings, skill_path, frontmatter, line_count)


def _report(
    validation_input: SkillValidationInput,
    gaps: list[str],
    warnings: list[str],
    skill_path: Path,
    frontmatter: dict[str, str],
    line_count: int,
) -> JsonMap:
    status = "rework_required" if gaps else "skill_ready"
    return {
        "status": status,
        "requires_rework": bool(gaps),
        "principle": "Skills are reusable capabilities and must include trigger clarity, validation, forward-testing, and an improvement loop.",
        "checks": {
            "skill_path": str(skill_path),
            "frontmatter_name": frontmatter.get("name", ""),
            "description_present": bool(frontmatter.get("description", "").strip()),
            "skill_md_line_count": line_count,
            "trigger_examples_count": len(validation_input.trigger_examples),
            "validation_steps_count": len(validation_input.validation_steps),
            "forward_test_scenarios_count": len(validation_input.forward_test_scenarios),
            "improvement_ideas_count": len(validation_input.improvement_ideas),
        },
        "gaps": gaps,
        "warnings": warnings,
        "follow_up_actions": [f"Resolve skill gap: {gap}" for gap in gaps]
        + [f"Consider skill improvement: {warning}" for warning in warnings],
    }


def _parse_frontmatter(content: str) -> tuple[dict[str, str], str, str]:
    if not content.startswith("---"):
        return {}, "", "SKILL.md frontmatter is missing."
    match = re.match(r"^---\n(.*?)\n---\n?(.*)$", content, re.DOTALL)
    if not match:
        return {}, "", "SKILL.md frontmatter format is invalid."
    frontmatter: dict[str, str] = {}
    for line in match.group(1).splitlines():
        if not line.strip():
            continue
        if ":" not in line:
            return {}, "", f"Invalid frontmatter line: {line}."
        key, value = line.split(":", 1)
        frontmatter[key.strip()] = value.strip().strip('"').strip("'")
    return frontmatter, match.group(2), ""


def _validate_frontmatter(frontmatter: dict[str, str], folder_name: str) -> list[str]:
    gaps = []
    unexpected = set(frontmatter) - {"name", "description"}
    if unexpected:
        gaps.append(f"Unexpected SKILL.md frontmatter keys: {', '.join(sorted(unexpected))}.")
    name = frontmatter.get("name", "").strip()
    description = frontmatter.get("description", "").strip()
    if not name:
        gaps.append("Frontmatter name is missing.")
    elif not re.match(r"^[a-z0-9-]+$", name):
        gaps.append("Frontmatter name must use lowercase hyphen-case.")
    elif name.startswith("-") or name.endswith("-") or "--" in name:
        gaps.append("Frontmatter name cannot start/end with hyphen or contain consecutive hyphens.")
    elif len(name) > MAX_SKILL_NAME_LENGTH:
        gaps.append(f"Frontmatter name is too long; maximum is {MAX_SKILL_NAME_LENGTH} characters.")
    elif name != folder_name:
        gaps.append("Frontmatter name must match the skill folder name.")

    if not description:
        gaps.append("Frontmatter description is missing.")
    elif "[TODO" in description or "TODO" in description:
        gaps.append("Frontmatter description still contains TODO text.")
    else:
        if len(description) < 80:
            gaps.append("Frontmatter description is too short to reliably trigger the skill.")
        if "when" not in description.lower() and "use for" not in description.lower():
            gaps.append("Frontmatter description must include when to use the skill.")
    return gaps


def _validate_body(body: str) -> list[str]:
    gaps = []
    stripped = body.strip()
    if not stripped:
        gaps.append("SKILL.md body is missing.")
    if "TODO" in body:
        gaps.append("SKILL.md body still contains TODO text.")
    return gaps


def _body_warnings(body: str) -> list[str]:
    warnings = []
    if "validation" not in body.lower() and "validate" not in body.lower():
        warnings.append("SKILL.md should mention how the skill is validated.")
    if "forward" not in body.lower() and "test" not in body.lower():
        warnings.append("SKILL.md should mention forward-testing or realistic usage tests.")
    return warnings


def _required_string(data: JsonMap, field_name: str) -> str:
    value = data.get(field_name)
    if not isinstance(value, str):
        raise TypeError(f"{field_name} must be a string.")
    return value


def _tuple_of_strings(value: Any, field_name: str) -> tuple[str, ...]:
    if not isinstance(value, list | tuple):
        raise TypeError(f"{field_name} must be a list of strings.")
    if not all(isinstance(item, str) for item in value):
        raise TypeError(f"{field_name} must contain only strings.")
    return tuple(value)

"""Validate that shared JSON config files are self-documenting."""

from __future__ import annotations

from typing import Any


JsonMap = dict[str, Any]

REQUIRED_TOP_LEVEL_FIELDS = {
    "schema_version",
    "name",
    "purpose",
    "reader_guide",
    "reference_links",
    "structure_rules",
    "field_guide",
}

REQUIRED_READER_GUIDE_FIELDS = {"summary", "how_to_read", "owner", "last_reviewed", "update_triggers"}
REQUIRED_REFERENCE_FIELDS = {"id", "title", "source_type", "used_for", "last_checked"}
REQUIRED_STRUCTURE_RULE_FIELDS = {"id", "rule", "reason", "applies_to"}
REQUIRED_FIELD_GUIDE_FIELDS = {"field", "meaning", "required"}


def check_config_contract(config: JsonMap, path: str = "") -> JsonMap:
    """Return whether a settings file explains its references and structure in-place."""

    gaps: list[str] = []
    warnings: list[str] = []
    label = path or _optional_string(config.get("name", "config"), "name")

    missing_top_fields = sorted(REQUIRED_TOP_LEVEL_FIELDS - set(config))
    if missing_top_fields:
        gaps.append(f"{label}: missing top-level self-documenting fields: {', '.join(missing_top_fields)}.")

    _check_reader_guide(config.get("reader_guide"), label, gaps)
    _check_reference_links(config.get("reference_links"), label, gaps, warnings)
    _check_structure_rules(config.get("structure_rules"), label, gaps)
    _check_field_guide(config.get("field_guide"), label, gaps)

    status = "self_documenting" if not gaps else "documentation_contract_required"

    return {
        "status": status,
        "requires_rework": bool(gaps),
        "principle": "A shared config file must explain its purpose, references, structure rules, and important fields inside the file itself.",
        "checks": {
            "top_level_fields_count": len(config),
            "reference_links_count": _safe_len(config.get("reference_links")),
            "structure_rules_count": _safe_len(config.get("structure_rules")),
            "field_guide_count": _safe_len(config.get("field_guide")),
        },
        "gaps": gaps,
        "warnings": warnings,
        "follow_up_actions": [f"Resolve config contract gap: {gap}" for gap in gaps],
    }


def _check_reader_guide(value: Any, label: str, gaps: list[str]) -> None:
    if not isinstance(value, dict):
        gaps.append(f"{label}: reader_guide must be an object.")
        return
    missing = sorted(REQUIRED_READER_GUIDE_FIELDS - set(value))
    if missing:
        gaps.append(f"{label}: reader_guide missing fields: {', '.join(missing)}.")
    if not _non_empty_string(value.get("summary")):
        gaps.append(f"{label}: reader_guide.summary must explain the config in plain language.")
    if not _list_of_non_empty_strings(value.get("how_to_read")):
        gaps.append(f"{label}: reader_guide.how_to_read must list how a human or agent should read this file.")
    if not _list_of_non_empty_strings(value.get("update_triggers")):
        gaps.append(f"{label}: reader_guide.update_triggers must list when to update this file.")


def _check_reference_links(value: Any, label: str, gaps: list[str], warnings: list[str]) -> None:
    if not isinstance(value, list) or not value:
        gaps.append(f"{label}: reference_links must be a non-empty list.")
        return

    for index, item in enumerate(value, start=1):
        item_label = f"{label}: reference_links[{index}]"
        if not isinstance(item, dict):
            gaps.append(f"{item_label} must be an object.")
            continue
        missing = sorted(REQUIRED_REFERENCE_FIELDS - set(item))
        if missing:
            gaps.append(f"{item_label} missing fields: {', '.join(missing)}.")
        if not (_non_empty_string(item.get("url")) or _non_empty_string(item.get("path"))):
            gaps.append(f"{item_label} must include url or path.")
        if not _list_of_non_empty_strings(item.get("used_for")):
            gaps.append(f"{item_label}.used_for must be a non-empty list.")
        if _non_empty_string(item.get("url")) and not _non_empty_string(item.get("last_checked")):
            gaps.append(f"{item_label} external URL needs last_checked.")
        if item.get("source_type") == "social":
            warnings.append(f"{item_label} is a social source; use it as discovery or adoption signal, not proof.")


def _check_structure_rules(value: Any, label: str, gaps: list[str]) -> None:
    if not isinstance(value, list) or not value:
        gaps.append(f"{label}: structure_rules must be a non-empty list.")
        return

    for index, item in enumerate(value, start=1):
        item_label = f"{label}: structure_rules[{index}]"
        if not isinstance(item, dict):
            gaps.append(f"{item_label} must be an object.")
            continue
        missing = sorted(REQUIRED_STRUCTURE_RULE_FIELDS - set(item))
        if missing:
            gaps.append(f"{item_label} missing fields: {', '.join(missing)}.")
        if not _non_empty_string(item.get("rule")):
            gaps.append(f"{item_label}.rule must be non-empty.")


def _check_field_guide(value: Any, label: str, gaps: list[str]) -> None:
    if not isinstance(value, list) or not value:
        gaps.append(f"{label}: field_guide must be a non-empty list.")
        return

    fields_seen = set()
    for index, item in enumerate(value, start=1):
        item_label = f"{label}: field_guide[{index}]"
        if not isinstance(item, dict):
            gaps.append(f"{item_label} must be an object.")
            continue
        missing = sorted(REQUIRED_FIELD_GUIDE_FIELDS - set(item))
        if missing:
            gaps.append(f"{item_label} missing fields: {', '.join(missing)}.")
        field_name = item.get("field")
        if not _non_empty_string(field_name):
            gaps.append(f"{item_label}.field must be non-empty.")
        elif field_name in fields_seen:
            gaps.append(f"{item_label}.field is duplicated: {field_name}.")
        else:
            fields_seen.add(field_name)
        if not _non_empty_string(item.get("meaning")):
            gaps.append(f"{item_label}.meaning must be non-empty.")
        if not isinstance(item.get("required"), bool):
            gaps.append(f"{item_label}.required must be a bool.")


def _non_empty_string(value: Any) -> bool:
    return isinstance(value, str) and bool(value.strip())


def _list_of_non_empty_strings(value: Any) -> bool:
    return isinstance(value, list) and bool(value) and all(_non_empty_string(item) for item in value)


def _safe_len(value: Any) -> int:
    return len(value) if isinstance(value, list) else 0


def _optional_string(value: Any, field_name: str) -> str:
    if not isinstance(value, str):
        raise TypeError(f"{field_name} must be a string.")
    return value

"""Installation mode registry helpers."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any


REQUIRED_TOP_LEVEL_FIELDS = {
    "schema_version",
    "name",
    "purpose",
    "reader_guide",
    "reference_links",
    "structure_rules",
    "field_guide",
    "mode_boundary",
    "default_mode",
    "modes",
    "selection_rules",
}

REQUIRED_MODE_FIELDS = {
    "id",
    "label",
    "intent",
    "audience",
    "dependency_policy",
    "allowed_actions",
    "must_not",
    "commands",
    "verification",
}

REQUIRED_COMMAND_FIELDS = {"id", "project", "purpose", "command"}


def load_install_mode_registry(path: Path) -> dict[str, Any]:
    """Load an installation mode registry JSON file."""

    with path.open("r", encoding="utf-8") as file:
        data = json.load(file)
    if not isinstance(data, dict):
        raise ValueError("Install mode registry must be a JSON object.")
    return data


def list_install_modes(registry: dict[str, Any]) -> list[dict[str, str]]:
    """Return a compact list of install modes."""

    return [
        {
            "id": mode["id"],
            "label": mode["label"],
            "intent": mode["intent"],
        }
        for mode in _mode_records(registry)
    ]


def show_install_mode(registry: dict[str, Any], mode_id: str) -> dict[str, Any]:
    """Return one install mode by id."""

    for mode in _mode_records(registry):
        if mode.get("id") == mode_id:
            return mode
    raise ValueError(f"Unknown install mode '{mode_id}'.")


def check_install_mode_registry(registry: dict[str, Any]) -> dict[str, Any]:
    """Validate the registry shape and user/developer install split."""

    gaps: list[str] = []
    warnings: list[str] = []

    missing = sorted(REQUIRED_TOP_LEVEL_FIELDS - set(registry))
    if missing:
        gaps.append(f"Missing top-level fields: {', '.join(missing)}.")

    modes = registry.get("modes")
    if not isinstance(modes, list) or not modes:
        gaps.append("modes must be a non-empty list.")
        modes = []

    mode_ids: list[str] = []
    for index, mode in enumerate(modes, start=1):
        if not isinstance(mode, dict):
            gaps.append(f"modes[{index}] must be an object.")
            continue
        mode_id = str(mode.get("id", "")).strip()
        if mode_id:
            mode_ids.append(mode_id)
        missing_mode_fields = sorted(REQUIRED_MODE_FIELDS - set(mode))
        if missing_mode_fields:
            gaps.append(f"mode {mode_id or index}: missing fields: {', '.join(missing_mode_fields)}.")

        commands = mode.get("commands")
        if not isinstance(commands, list) or not commands:
            gaps.append(f"mode {mode_id or index}: commands must be a non-empty list.")
            commands = []
        for command_index, command in enumerate(commands, start=1):
            if not isinstance(command, dict):
                gaps.append(f"mode {mode_id or index} command {command_index}: must be an object.")
                continue
            missing_command_fields = sorted(REQUIRED_COMMAND_FIELDS - set(command))
            if missing_command_fields:
                gaps.append(
                    f"mode {mode_id or index} command {command.get('id', command_index)}: "
                    f"missing fields: {', '.join(missing_command_fields)}."
                )

    if "user" not in mode_ids:
        gaps.append("A user install mode is required.")
    if "developer" not in mode_ids:
        gaps.append("A developer install mode is required.")
    if len(mode_ids) != len(set(mode_ids)):
        gaps.append("Install mode ids must be unique.")

    default_mode = registry.get("default_mode")
    if default_mode not in mode_ids:
        gaps.append("default_mode must match one modes[].id.")

    if registry.get("mode_boundary") and "work_mode" not in registry.get("mode_boundary", {}):
        warnings.append("mode_boundary should explain work_mode so install mode and work mode stay distinct.")

    return {
        "status": "ready" if not gaps else "rework_required",
        "requires_rework": bool(gaps),
        "checks": {
            "mode_count": len(mode_ids),
            "mode_ids": mode_ids,
            "default_mode": default_mode,
        },
        "gaps": gaps,
        "warnings": warnings,
        "follow_up_actions": [f"Resolve gap: {gap}" for gap in gaps],
    }


def _mode_records(registry: dict[str, Any]) -> list[dict[str, Any]]:
    modes = registry.get("modes", [])
    if not isinstance(modes, list):
        raise ValueError("modes must be a list.")
    return [mode for mode in modes if isinstance(mode, dict)]

