    .pa-deck {{
      width: 100vw;
      height: 100vh;
      display: grid;
      place-items: center;
      padding: min(3vw, 32px);
    }}
    .pa-slide {{
      display: none;
      width: min(100%, calc(100vh * 16 / 9 - 64px));
      max-width: 1280px;
      aspect-ratio: 16 / 9;
      background: var(--pa-surface);
      border: 1px solid var(--pa-line);
      box-shadow: 0 18px 60px rgb(0 0 0 / 14%);
