    .pa-slide--closing .pa-slide__frame {{
      grid-template-columns: 1fr;
      align-content: center;
    }}
    .pa-slide__content {{
      min-width: 0;
      align-self: center;
    }}
    .pa-kicker {{
      margin: 0 0 18px;
