      font-size: clamp(14px, 1.4vw, 18px);
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0;
    }}
    h1 {{
      margin: 0;
      max-width: 11ch;
      font-family: var(--pa-display);
      font-size: clamp(44px, 6vw, 84px);
