      padding: 18px;
      box-shadow: 0 16px 42px rgb(0 0 0 / 14%);
    }}
    body.show-notes .pa-presenter {{ transform: translateX(0); }}
    .pa-presenter__label {{
      color: var(--pa-accent);
      font-size: 12px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0;
    }}
    .pa-presenter__beat {{
      margin-top: 8px;
      font-weight: 700;
      font-size: 18px;
    }}
    .pa-presenter__notes {{
      margin: 14px 0 0;
      padding-left: 20px;
      color: var(--pa-muted);
      line-height: 1.45;
    }}
    @media (max-width: 760px) {{
      body {{ overflow: auto; }}
      .pa-deck {{ height: auto; padding: 0; }}
      .pa-slide {{
        display: block;
        width: 100%;
        min-height: 100svh;
        aspect-ratio: auto;
        border: 0;
        box-shadow: none;
      }}
      .pa-slide:not(.is-active) {{ display: none; }}
      .pa-slide__frame {{
        grid-template-columns: 1fr;
        min-height: 100svh;
        padding: 34px 24px 86px;
      }}
      .pa-visual {{ border-left: 0; border-top: 1px solid var(--pa-line); padding: 24px 0 0; }}
      h1, .pa-slide--split h1, .pa-slide--evidence h1, .pa-slide--process h1 {{ font-size: 42px; }}
      .pa-controls {{ bottom: 12px; }}
    }}
    @media print {{
      body {{ overflow: visible; background: white; }}
      .pa-deck {{ display: block; width: auto; height: auto; padding: 0; }}
      .pa-slide {{ display: block; width: 100vw; height: 100vh; page-break-after: always; box-shadow: none; border: 0; }}
      .pa-controls, .pa-progress, .pa-presenter {{ display: none; }}
    }}
"""


def _deck_js() -> str:
    return """
    let currentSlide = 0;
    const slides = Array.from(document.querySelectorAll('.pa-slide'));
    const progress = document.querySelector('.pa-progress span');
    const count = document.querySelector('.pa-count');
    const notesList = document.querySelector('.pa-presenter__notes');
    const beat = document.querySelector('.pa-presenter__beat');

    function showSlide(index) {
      currentSlide = Math.max(0, Math.min(index, slides.length - 1));
      slides.forEach((slide, slideIndex) => {
        slide.classList.toggle('is-active', slideIndex === currentSlide);
      });
      count.value = `${currentSlide + 1} / ${slides.length}`;
      progress.style.width = `${((currentSlide + 1) / slides.length) * 100}%`;
      beat.textContent = scriptBeats[currentSlide] || '';
      notesList.innerHTML = '';
      (speakerNotes[currentSlide] || []).forEach((note) => {
        const item = document.createElement('li');
        item.textContent = note;
        notesList.appendChild(item);
      });
    }

    function nextSlide() { showSlide(currentSlide + 1); }
    function previousSlide() { showSlide(currentSlide - 1); }

    document.addEventListener('keydown', (event) => {
      if (['ArrowRight', 'PageDown', ' '].includes(event.key)) {
        event.preventDefault();
        nextSlide();
      }
      if (['ArrowLeft', 'PageUp', 'Backspace'].includes(event.key)) {
        event.preventDefault();
        previousSlide();
      }
      if (event.key.toLowerCase() === 's') {
        document.body.classList.toggle('show-notes');
      }
    });

    document.querySelector('[data-action="prev"]').addEventListener('click', previousSlide);
    document.querySelector('[data-action="next"]').addEventListener('click', nextSlide);
    document.querySelector('[data-action="notes"]').addEventListener('click', () => {
      document.body.classList.toggle('show-notes');
    });

    showSlide(0);
"""


def main(argv: list[st

import { expect, test } from '@playwright/test';
import type { Page } from '@playwright/test';
import AxeBuilder from '@axe-core/playwright';
import fs from 'node:fs';
import path from 'node:path';
import { pathToFileURL } from 'node:url';

const artifactsDir = path.resolve(__dirname, '../../artifacts/html');
const deckFiles = fs
  .readdirSync(artifactsDir)
  .filter((fileName) => fileName.endsWith('.html'))
  .filter((fileName) => fs.readFileSync(path.join(artifactsDir, fileName), 'utf8').includes('pa-slide'))
  .sort();

test.describe('generated HTML presentation decks', () => {
  for (const deckFile of deckFiles) {
    test(`${deckFile} renders, navigates, and exposes presenter controls`, async ({ page }) => {
      const deckUrl = pathToFileURL(path.join(artifactsDir, deckFile)).href;

      await page.goto(deckUrl);

      const slides = page.locator('.pa-slide');
      const slideCount = await slides.count();
      expect(slideCount).toBeGreaterThan(0);

      const activeSlide = page.locator('.pa-slide.is-active');
      await expect(activeSlide).toBeVisible();
      await expect(activeSlide.locator('h1')).toBeVisible();

      const activeSlideText = await activeSlide.innerText();
      expect(activeSlideText.trim().length).toBeGreaterThan(20);

      const activeSlideBox = await activeSlide.boundingBox();
      expect(activeSlideBox?.width ?? 0).toBeGreaterThan(250);
      expect(activeSlideBox?.height ?? 0).toBeGreaterThan(160);

      await expect(page.locator('.pa-controls')).toBeVisible();
      await expect(page.locator('[data-action="next"]')).toBeVisible();
      await expect(page.locator('[data-action="prev"]')).toBeVisible();
      await expect(page.locator('[data-action="notes"]')).toBeVisible();

      const initialCount = await currentSlideCount(page);
      expect(initialCount).toMatch(new RegExp(`^1 / ${slideCount}$`));

      if (slideCount > 1) {
        await page.keyboard.press('ArrowRight');
        await expect.poll(() => currentSlideCount(page)).toBe(`2 / ${slideCount}`);

        const secondSlideText = await activeSlide.innerText();
        expect(secondSlideText.trim().length).toBeGreaterThan(20);

        await page.keyboard.press('ArrowLeft');
        await expect.poll(() => currentSlideCount(page)).toBe(`1 / ${slideCount}`);
      }

      await page.keyboard.press('s');
      await expect(page.locator('body')).toHaveClass(/show-notes/);
      await expect(page.locator('.pa-presenter')).toBeVisible();
    });

    test(`${deckFile} has no automated axe accessibility violations`, async ({ page }) => {
      const deckUrl = pathToFileURL(path.join(artifactsDir, deckFile)).href;

      await page.goto(deckUrl);

      const results = await new AxeBuilder({ page }).analyze();
      expect(results.violations).toEqual([]);
    });
  }
});

async function currentSlideCount(page: Page): Promise<string> {
  return page.locator('.pa-count').evaluate((element) => {
    if (element instanceof HTMLOutputElement) {
      return element.value;
    }
    return element.textContent ?? '';
  });
}

