      {
        id: "task-blocked",
        title: "Blocked work",
        status: "pending",
        agent: "runner-agent",
        project: "demo",
        blockers: ["needs decision"]
      },
      { id: "task-done", title: "Done work", status: "completed", agent: "runner-agent", project: "demo" }
    ]
  );

  assert.equal(board.summary.activeTasks, 1);
  assert.equal(board.summary.blockedTasks, 1);
